#include <string>
#include <string_view>

class Animal
{
public:
    explicit Animal(std::string_view name) : m_name{ name } {}
    const std::string& name() const { return m_name; }
    std::string eat() const { return m_name + " eats."; }

private:
    std::string m_name{};
};

class Dog : public Animal
{
public:
    explicit Dog(std::string_view name) : Animal{ name } {}
    std::string fetch() const { return name() + " fetches!"; }
};

unitTests:
static_assert(std::is_base_of_v<Animal, Dog>, "Dog should inherit from Animal");
TEST("a dog is an animal") { const Dog rex{ "Rex" }; CHECK_EQ(rex.name(), "Rex"); CHECK_EQ(rex.eat(), "Rex eats."); }
TEST("and has something of its own") { CHECK_EQ(Dog{ "Rex" }.fetch(), "Rex fetches!"); }
TEST("a dog can be used wherever an animal is expected") { const Dog d{ "Fido" }; const Animal& a{ d }; CHECK_EQ(a.name(), "Fido"); }

